<template>
  <div v-if="!ready" class="boot">正在连接运营中心…</div>
  <main v-else-if="!loggedIn" class="login-page">
    <section class="login-card"><div class="brand-mark">C</div><p class="eyebrow">CANGSHUO · CONTROL CENTER</p><h1>授权运营中心</h1><p class="muted">管理客户、模块、授权与版本发布</p>
      <el-form label-position="top" @submit.prevent="login"><el-form-item label="运营账号"><el-input v-model="credentials.username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="credentials.password" type="password" autocomplete="current-password" show-password /></el-form-item><el-button native-type="submit" type="primary" :loading="busy" class="login-submit">登录运营后台</el-button></el-form>
    </section>
  </main>
  <div v-else class="shell">
    <aside><div class="brand"><div class="brand-mark">C</div><div><strong>沧烁授权中心</strong><small>系统运营工作台</small></div></div><div class="nav-label">平台运营</div><button v-for="item in navigation" :key="item.id" :class="{selected:page===item.id}" @click="page=item.id"><component :is="item.icon"/><span>{{ item.name }}</span></button><div class="aside-bottom">独立运营后台<br/>客户业务系统单独维护</div></aside>
    <div class="workspace"><header><div><span class="breadcrumb">平台运营 / </span><strong>{{ title }}</strong></div><div class="header-actions"><el-tag type="info">人工开通</el-tag><span>{{ username }}</span><el-button text @click="logout">退出</el-button></div></header>
      <section class="content" v-loading="busy">
        <div class="page-heading"><div><p class="eyebrow">{{ page==='overview'?'CONTROL CENTER':'PLATFORM MANAGEMENT' }}</p><h1>{{ title }}</h1><p class="muted">{{ descriptions[page] }}</p></div><div class="actions"><el-button @click="refresh">刷新</el-button><el-button v-if="createActions[page]" type="primary" @click="open(createActions[page])">{{ createLabels[page] }}</el-button><el-button v-if="page==='licenses'" type="primary" @click="showPublicKey">查看验证公钥</el-button></div></div>
        <template v-if="page==='overview'">
          <div class="stats"><article v-for="item in stats" :key="item.name"><span>{{ item.name }}</span><strong>{{ item.value }}</strong><small>{{ item.detail }}</small></article></div>
          <el-card shadow="never"><template #header><div class="section-title">开通流程 <el-tag type="info" size="small">首版人工收款</el-tag></div></template><div class="steps"><div v-for="(step,index) in ['登记客户和实例','配置模块价格','创建订单并核对收款','签发授权，交付客户导入']" :key="step"><b>{{ index+1 }}</b><span>{{ step }}</span></div></div><p class="muted">平台只记录人工核对结果，不会自动扣款。客户系统仅使用验证公钥；签发私钥保留在本运营中心。</p></el-card>
          <el-card shadow="never" class="panel"><template #header>最近操作</template><el-table :data="data.audit.slice(0,6)" stripe><el-table-column label="时间" min-width="180"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column><el-table-column prop="actor" label="运营账号"/><el-table-column label="操作" min-width="170"><template #default="{row}">{{ actionLabels[row.action] || row.action }}</template></el-table-column><el-table-column prop="target" label="关联编号" min-width="240" show-overflow-tooltip/></el-table></el-card>
        </template>
        <el-card v-else shadow="never"><div class="table-toolbar"><strong>{{ title }}列表</strong><el-input v-model="search" placeholder="搜索编号、名称或状态" clearable class="search"/></div>
          <el-table v-if="page==='customers'" :data="records" stripe><el-table-column prop="id" label="客户编号" min-width="130"/><el-table-column prop="name" label="客户名称" min-width="180"/><el-table-column label="状态"><template #default="{row}"><el-tag type="success">{{ status(row.status) }}</el-tag></template></el-table-column><el-table-column prop="note" label="备注" min-width="200" show-overflow-tooltip/><el-table-column label="登记时间" min-width="180"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column></el-table>
          <el-table v-if="page==='instances'" :data="records" stripe><el-table-column prop="name" label="实例名称" min-width="140"/><el-table-column prop="customer_name" label="所属客户" min-width="140"/><el-table-column prop="id" label="实例编号" min-width="300"/><el-table-column label="域名授权" min-width="220"><template #default="{row}">{{ (row.domains||[]).join('、') }}</template></el-table-column><el-table-column label="维护期至" min-width="180"><template #default="{row}">{{ time(row.maintenance_until) }}</template></el-table-column><el-table-column prop="client_version" label="客户端版本" min-width="160"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open('instance',row)">编辑</el-button></template></el-table-column></el-table>
          <el-table v-if="page==='modules'" :data="records" stripe><el-table-column prop="name" label="模块名称" min-width="150"/><el-table-column prop="id" label="模块编号" min-width="220"/><el-table-column label="价格"><template #default="{row}">{{ row.price_cents==null?'尚未定价':money(row.price_cents) }}</template></el-table-column><el-table-column label="授权期限"><template #default="{row}">{{ row.term_days===0?'永久':row.term_days+' 天' }}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{ status(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open('module',row)">设置价格与上架</el-button></template></el-table-column></el-table>
          <el-table v-if="page==='orders'" :data="records" stripe><el-table-column prop="id" label="订单编号" min-width="280"/><el-table-column prop="customer_name" label="客户" min-width="130"/><el-table-column prop="module_name" label="功能模块" min-width="150"/><el-table-column label="订单金额"><template #default="{row}">{{ money(row.amount_cents) }}</template></el-table-column><el-table-column label="状态" min-width="140"><template #default="{row}"><el-tag :type="row.granted_at?'success':row.status==='PAID'?'warning':'info'">{{ row.granted_at?'已交付授权':status(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="200"><template #default="{row}"><el-button v-if="row.status==='UNPAID'" link type="primary" @click="open('payment',row)">确认收款</el-button><el-button v-if="row.status==='UNPAID'" link type="primary" @click="maintenanceGrant(row)">维护期接入</el-button><el-button v-if="row.status==='PAID'||row.status==='MAINTENANCE'" link type="primary" @click="issue(row)">{{ row.granted_at?'查看授权':'签发授权' }}</el-button></template></el-table-column></el-table>
          <el-table v-if="page==='licenses'" :data="records" stripe><el-table-column prop="id" label="授权编号" min-width="290"/><el-table-column prop="customer_id" label="客户编号" min-width="120"/><el-table-column prop="instance_id" label="绑定实例" min-width="300"/><el-table-column label="域名授权" min-width="200"><template #default="{row}">{{ (row.domains||[]).join('、') }}</template></el-table-column><el-table-column label="签发时间" min-width="180"><template #default="{row}">{{ time(row.issued_at) }}</template></el-table-column><el-table-column label="维护期/授权到期" min-width="180"><template #default="{row}">{{ time(row.expires_at) }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="viewLicense(row)">查看交付内容</el-button></template></el-table-column></el-table>
          <el-table v-if="page==='releases'" :data="records" stripe><el-table-column prop="version" label="版本号" min-width="180"/><el-table-column label="通道"><template #default="{row}">{{ row.channel==='stable'?'正式版':'预览版' }}</template></el-table-column><el-table-column prop="notes" label="更新说明" min-width="220" show-overflow-tooltip/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':'info'">{{ status(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="170"><template #default="{row}"><el-button v-if="row.status==='DRAFT'" link type="primary" @click="publish(row)">发布版本信息</el-button><a :href="row.source_url" target="_blank" rel="noopener noreferrer">GitHub Release</a></template></el-table-column></el-table>
          <el-table v-if="page==='audit'" :data="records" stripe><el-table-column label="时间" min-width="180"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column><el-table-column prop="actor" label="运营账号"/><el-table-column label="操作" min-width="180"><template #default="{row}">{{ actionLabels[row.action] || row.action }}</template></el-table-column><el-table-column prop="target" label="关联编号" min-width="280"/><el-table-column prop="detail" label="操作记录" min-width="240" show-overflow-tooltip/></el-table>
        </el-card>
      </section>
    </div>
    <el-dialog v-model="dialog" :title="dialogTitle" width="min(580px,94vw)" destroy-on-close>
      <el-form label-position="top" @submit.prevent="save">
        <template v-if="kind==='customer'"><el-form-item label="客户编号"><el-input v-model="form.id" placeholder="如 742，须与客户系统配置一致"/></el-form-item><el-form-item label="客户名称"><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note" type="textarea" maxlength="500"/></el-form-item></template>
        <template v-if="kind==='instance'"><el-form-item v-if="!form.editing" label="所属客户"><el-select v-model="form.customerId" placeholder="选择客户"><el-option v-for="customer in data.customers" :key="customer.id" :value="customer.id" :label="customer.name+' · '+customer.id"/></el-select></el-form-item><el-form-item v-if="!form.editing" label="实例编号"><el-input v-model="form.id" placeholder="从客户后台功能商城复制 UUID"/></el-form-item><el-form-item label="实例名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="域名授权（每行或逗号分隔）"><el-input v-model="form.domainsText" type="textarea" :rows="3" placeholder="jaxapi.kkimg.top&#10;jax.kkimg.top"/><span class="muted">客户付费功能只能通过这里列出的域名使用；支持 *.example.com 子域名授权。</span></el-form-item><el-form-item label="维护期至（即授权到期时间）"><el-input v-model="form.maintenanceUntil" placeholder="2027-11-01T23:59:59+08:00"/><span class="muted">必须填写带时区的 ISO 时间，签发授权不会超过此时间。</span></el-form-item><el-form-item label="客户端版本"><el-input v-model="form.clientVersion" placeholder="如 1.1.0-preview.2"/></el-form-item></template>
        <template v-if="kind==='module'"><p>{{ form.name }} · {{ form.id }}</p><el-form-item label="价格（元）"><el-input-number v-model="form.priceYuan" :precision="2" :min="0" :max="1000000"/></el-form-item><el-form-item label="授权天数（0 为永久）"><el-input-number v-model="form.termDays" :min="0" :max="3660"/></el-form-item><el-form-item label="上架状态"><el-select v-model="form.status"><el-option label="草稿" value="DRAFT"/><el-option label="已上架" value="ACTIVE"/></el-select></el-form-item></template>
        <template v-if="kind==='order'"><el-form-item label="客户实例"><el-select v-model="form.instanceId" placeholder="选择客户实例" filterable><el-option v-for="instance in data.instances" :key="instance.id" :value="instance.id" :label="instance.customer_name+' / '+instance.name"/></el-select></el-form-item><el-form-item label="功能模块"><el-select v-model="form.moduleId" placeholder="选择已定价上架的模块"><el-option v-for="module in data.modules.filter(item=>item.status==='ACTIVE')" :key="module.id" :value="module.id" :label="module.name+' · '+money(module.price_cents)"/></el-select></el-form-item><el-alert title="订单保存当时的价格与期限，后续改价不会改变已有订单。" type="info" :closable="false"/></template>
        <template v-if="kind==='payment'"><el-alert :title="'请核对实际收款 '+money(form.amount_cents)+' 后再确认。本操作只记账，不会执行扣款。'" type="warning" :closable="false"/><el-form-item label="收款核对凭据 / 备注"><el-input v-model="form.reference" placeholder="填写核对凭据或内部单号" maxlength="200"/></el-form-item></template>
        <template v-if="kind==='release'"><el-form-item label="版本号"><el-input v-model="form.version" placeholder="1.1.0-preview.2"/></el-form-item><el-form-item label="发布通道"><el-select v-model="form.channel"><el-option label="预览版" value="preview"/><el-option label="正式版" value="stable"/></el-select></el-form-item><el-form-item label="更新说明"><el-input v-model="form.notes" type="textarea" :rows="4" maxlength="4000"/></el-form-item><el-form-item label="客户端仓库的 GitHub Release 地址"><el-input v-model="form.sourceUrl" placeholder="https://github.com/zhz520/cangshuo-detla/releases/tag/..."/></el-form-item><el-alert title="这里登记版本信息；不会自动构建软件或安装到客户服务器。" type="info" :closable="false"/></template>
      </el-form>
      <template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{ kind==='payment'?'已核对，确认收款':'保存' }}</el-button></template>
    </el-dialog>
    <el-dialog v-model="deliveryVisible" :title="deliveryType==='key'?'客户系统验证公钥':'授权交付内容'" width="min(720px,94vw)"><p class="muted">{{ deliveryType==='key'?'将公钥配置到客户系统。此处不包含签发私钥。':'客户在功能商城导入完整 JSON 后，启用已授权模块。内容只适用于绑定的客户与实例。' }}</p><el-input :model-value="deliveryText" type="textarea" :rows="11" readonly/><template #footer><el-button @click="copyDelivery">复制内容</el-button><el-button type="primary" @click="downloadDelivery">下载{{ deliveryType==='key'?'公钥':'授权文件' }}</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { HomeFilled, UserFilled, Monitor, Goods, Document, Key, UploadFilled, Clock } from '@element-plus/icons-vue'
const navigation=[{id:'overview',name:'运营概览',icon:HomeFilled},{id:'customers',name:'客户管理',icon:UserFilled},{id:'instances',name:'客户实例',icon:Monitor},{id:'modules',name:'功能与定价',icon:Goods},{id:'orders',name:'购买订单',icon:Document},{id:'licenses',name:'授权管理',icon:Key},{id:'releases',name:'版本发布',icon:UploadFilled},{id:'audit',name:'操作记录',icon:Clock}]
const descriptions={overview:'一个运营中心，管理所有客户的功能授权。',customers:'登记客户编号与名称，与客户系统独立维护。',instances:'将授权绑定到客户系统显示的实例编号。',modules:'先确认价格与期限，再开放人工购买。',orders:'核对人工收款后签发授权，不自动扣款。',licenses:'查看与交付签名授权，签发私钥留在运营中心。',releases:'维护客户端的版本目录与发布说明。',audit:'保留客户登记、收款确认和签发记录。'}
const actionLabels={LOGIN:'登录后台',CREATE_CUSTOMER:'登记客户',CREATE_INSTANCE:'登记实例',UPDATE_INSTANCE:'更新授权域名/维护期',UPDATE_MODULE:'调整模块价格',CREATE_ORDER:'创建购买订单',CONFIRM_MANUAL_PAYMENT:'确认人工收款',GRANT_MAINTENANCE_ACCESS:'维护期接入',ISSUE_LICENSE:'签发授权',CREATE_RELEASE_DRAFT:'登记版本草稿',PUBLISH_RELEASE_METADATA:'发布版本信息'}
const createActions={customers:'customer',instances:'instance',orders:'order',releases:'release'},createLabels={customers:'新增客户',instances:'登记实例',orders:'创建订单',releases:'新增版本'}
const ready=ref(false),loggedIn=ref(false),username=ref(''),csrf=ref(''),busy=ref(false),saving=ref(false),page=ref('overview'),search=ref('')
const credentials=reactive({username:'admin',password:''}),data=reactive({customers:[],instances:[],modules:[],orders:[],licenses:[],releases:[],audit:[]})
const title=computed(()=>navigation.find(item=>item.id===page.value)?.name)
const stats=computed(()=>[{name:'已登记客户',value:data.customers.length,detail:'独立客户档案'},{name:'客户实例',value:data.instances.length,detail:'按实例绑定授权'},{name:'待确认收款',value:data.orders.filter(order=>order.status==='UNPAID').length,detail:'人工核对后开通'},{name:'已签发授权',value:data.licenses.length,detail:'完整交付记录'}])
const records=computed(()=>{const list=data[page.value]||[];const query=search.value.trim().toLowerCase();return query?list.filter(row=>JSON.stringify(row).toLowerCase().includes(query)):list})
function money(cents){return '¥'+(Number(cents)/100).toFixed(2)}
function time(value){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
function status(value){return {ACTIVE:'已启用',DRAFT:'草稿',UNPAID:'待收款',PAID:'已收款',MAINTENANCE:'维护期接入',CANCELLED:'已作废',PUBLISHED:'已发布'}[value]||value}
async function api(url,{method='GET',body}={}){
  const headers={};if(method!=='GET'){headers['Content-Type']='application/json';headers['X-CSRF-Token']=csrf.value}
  const response=await fetch('/api'+url,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)})
  const result=await response.json();if(!response.ok){if(response.status===401)loggedIn.value=false;throw new Error(result.message||'操作失败')}return result
}
async function refresh(){busy.value=true;try{Object.assign(data,await api('/data'))}catch(error){ElMessage.error(error.message)}finally{busy.value=false}}
async function login(){busy.value=true;try{const session=await api('/login',{method:'POST',body:credentials});username.value=session.username;csrf.value=session.csrf;credentials.password='';loggedIn.value=true;await refresh()}catch(error){ElMessage.error(error.message)}finally{busy.value=false}}
async function logout(){try{await api('/logout',{method:'POST',body:{}});loggedIn.value=false;csrf.value=''}catch(error){ElMessage.error(error.message)}}
const dialog=ref(false),kind=ref(''),form=reactive({}),dialogTitle=computed(()=>({customer:'新增客户',instance:'登记客户实例',module:'配置功能价格',order:'创建购买订单',payment:'确认人工收款',release:'新增版本草稿'}[kind.value]))
function open(type,row={}){for(const key of Object.keys(form))delete form[key];kind.value=type;Object.assign(form,{channel:'preview',status:'DRAFT',termDays:365,...row});if(type==='module'){form.priceYuan=row.price_cents==null?undefined:row.price_cents/100;form.termDays=row.term_days}if(type==='instance'){form.domainsText=(row.domains||[]).join('\n');form.editing=!!row.id}if(type==='release')form.version='';dialog.value=true}
async function save(){saving.value=true;try{
  const instanceBody={name:form.name,domains:form.domainsText,maintenanceUntil:form.maintenanceUntil,clientVersion:form.clientVersion,customerId:form.customerId,id:form.id}
  const requests={customer:()=>api('/customers',{method:'POST',body:form}),instance:()=>form.editing?api(`/instances/${form.id}`,{method:'PUT',body:instanceBody}):api('/instances',{method:'POST',body:instanceBody}),order:()=>api('/orders',{method:'POST',body:form}),release:()=>api('/releases',{method:'POST',body:form}),payment:()=>api(`/orders/${form.id}/paid`,{method:'POST',body:{reference:form.reference}}),module:()=>api(`/modules/${form.id}`,{method:'PUT',body:{priceCents:form.priceYuan==null?null:Math.round(form.priceYuan*100),termDays:form.termDays,status:form.status}})}
  await requests[kind.value]();dialog.value=false;await refresh();ElMessage.success('已保存')
}catch(error){ElMessage.error(error.message)}finally{saving.value=false}}
const deliveryVisible=ref(false),deliveryType=ref('license'),deliveryText=ref(''),deliveryName=ref('')
async function issue(order){try{const result=await api(`/orders/${order.id}/issue`,{method:'POST',body:{}});deliveryType.value='license';deliveryName.value=result.id+'.license.json';deliveryText.value=JSON.stringify(result.envelope,null,2);deliveryVisible.value=true;await refresh()}catch(error){ElMessage.error(error.message)}}
async function viewLicense(license){try{deliveryText.value=JSON.stringify(await api('/licenses/'+license.id),null,2);deliveryType.value='license';deliveryName.value=license.id+'.license.json';deliveryVisible.value=true}catch(error){ElMessage.error(error.message)}}
async function maintenanceGrant(order){try{const result=await ElMessageBox.prompt('该操作只登记现有客户的维护期接入，不记为线上收款。请填写维护依据或内部单号。','维护期接入',{inputPlaceholder:'如：年度维护服务已续签',inputValidator:value=>value?.trim()?true:'请填写维护期接入说明'});await api(`/orders/${order.id}/maintenance`,{method:'POST',body:{note:result.value.trim()}});await refresh();ElMessage.success('已登记维护期接入')}catch(error){if(error?.message)ElMessage.error(error.message)}}
async function showPublicKey(){try{deliveryText.value=(await api('/public-key')).publicKey;deliveryType.value='key';deliveryName.value='license-public.pem';deliveryVisible.value=true}catch(error){ElMessage.error(error.message)}}
async function copyDelivery(){try{await navigator.clipboard.writeText(deliveryText.value);ElMessage.success('已复制')}catch{ElMessage.info('请手动选中并复制内容')}}
function downloadDelivery(){const url=URL.createObjectURL(new Blob([deliveryText.value],{type:'text/plain;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=deliveryName.value;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function publish(release){try{await ElMessageBox.confirm('请确认 GitHub Release 与说明已经核对。此操作发布版本信息，不执行客户服务器更新。','发布版本信息',{type:'info'});await api(`/releases/${encodeURIComponent(release.version)}/publish`,{method:'POST',body:{}});await refresh();ElMessage.success('版本信息已发布')}catch(error){if(error?.message)ElMessage.error(error.message)}}
onMounted(async()=>{try{const session=await api('/session');if(session.authenticated){loggedIn.value=true;username.value=session.username;csrf.value=session.csrf;await refresh()}}catch(error){ElMessage.error('运营服务连接失败：'+error.message)}finally{ready.value=true}})
</script>
